        if os.path.isfile(path):
            self.search_file(path)
            return

        for root, dirs, files in os.walk(path, followlinks=self.options.follow):
            if not self.options.hidden:
                dirs[:] = [d for d in dirs if not d.startswith('.')]
                files = [f for f in files if not f.startswith('.')]

            for file in files:
                file_path = os.path.join(root, file)
                if self.should_search(file_path):
                    self.search_file(file_path)

    def should_search(self, file_path):
        # Glob matching (-g)
        if self.options.glob:
            matched_any = False
            for g in self.options.glob:
                if fnmatch.fnmatch(file_path, g) or fnmatch.fnmatch(os.path.basename(file_path), g):
                    matched_any = True
                    break
            if not matched_any:
