                    content = f.read()
                    for m in self.pattern_re.finditer(content):
                        line_no = content.count('\n', 0, m.start()) + 1
                        line_content = content.splitlines()[line_no - 1]
                        self.results.append(Match(file_path, line_no, line_content))
                        self.total_matches += 1
                else:
                    for i, line in enumerate(f, 1):
                        if self.pattern_re.search(line):
                            self.results.append(Match(file_path, i, line.rstrip()))
                            self.total_matches += 1
        except Exception:
            pass

    def sort_results(self, sort_by, reverse=False):
        if not sort_by:
            return
        if sort_by == 'path':
            self.results.sort(key=lambda m: (m.file_path, m.line_number), reverse=reverse)
        elif sort_by == 'modified':
            self.results.sort(key=lambda m: os.path.getmtime(m.file_path), reverse=reverse)
        elif sort_by == 'created':
            self.results.sort(key=lambda m: os.path.getctime(m.file_path), reverse=reverse)
        elif sort_by == 'accessed':
            self.results.sort(key=lambda m: os.path.getatime(m.file_path), reverse=reverse)

