            curses.init_pair(3, curses.COLOR_BLACK, curses.COLOR_GREEN) # Status bar
            curses.init_pair(4, curses.COLOR_WHITE, 236 if curses.can_change_color() else curses.COLOR_BLACK) # Highlight background
        else:
            curses.init_pair(1, curses.COLOR_GREEN, -1)
            curses.init_pair(2, curses.COLOR_RED, -1)
            curses.init_pair(3, curses.COLOR_BLACK, curses.COLOR_GREEN)
            curses.init_pair(4, curses.COLOR_BLACK, 252 if curses.can_change_color() else curses.COLOR_WHITE)

